import 'package:flutter/material.dart'; import 'package:http/http.dart' as http; import 'package:shared_preferences/shared_preferences.dart'; import 'dart:convert'; import 'home_page.dart'; import 'register_page.dart'; class LoginPage extends StatefulWidget { @override _LoginPageState createState() => _LoginPageState(); } class _LoginPageState extends State<LoginPage> { TextEditingController email = TextEditingController(); TextEditingController password = TextEditingController(); Future<void> login() async { var url = Uri.parse('http://10.0.2.2/infoberita_news/login.php'); var response = await http.post(url, body: { 'email': email.text, 'password': password.text, }); var data = json.decode(response.body); if (data['status'] == 'success') { SharedPreferences prefs = await SharedPreferences.getInstance(); prefs.setBool('login', true); ScaffoldMessenger.of(context) .showSnackBar(SnackBar(content: Text('Login Berhasil'))); Navigator.pushReplacement( context, MaterialPageRoute(builder: (_) => HomePage()), ); } else { ScaffoldMessenger.of(context) .showSnackBar(SnackBar(content: Text('Login Gagal'))); } } @override Widget build(BuildContext context) { return Scaffold( appBar: AppBar(title: Text('Login')), body: Padding( padding: EdgeInsets.all(16), child: Column( children: [ TextField( controller: email, decoration: InputDecoration(labelText: 'Email'), ), TextField( controller: password, decoration: InputDecoration(labelText: 'Password'), obscureText: true, ), SizedBox(height: 20), ElevatedButton( onPressed: login, child: Text('Login'), ), TextButton( onPressed: () { Navigator.push( context, MaterialPageRoute(builder: (_) => RegisterPage()), ); }, child: Text('Belum punya akun? Register'), ), ], ), ), ); } }